UPDATE messages SET title=CASE WHEN title='Возвращение домой' THEN 'Возвращение в Рыбинск' ELSE title END,body=json_set(body,'$.trigger.label','Рыбинск','$.text',CASE WHEN json_extract(body,'$.text')='Ты дома. Можно больше не обниматься через экран. Мы с Чопой и Нафаней очень тебя ждали.' THEN 'Ты вернулась в Рыбинск. Можно больше не обниматься через экран. Мы с Чопой и Нафаней очень тебя ждали.' ELSE json_extract(body,'$.text') END) WHERE id IN(SELECT message_id FROM plans WHERE id='return-home') AND json_extract(body,'$.trigger.label')='Дом · Рыбинск';
UPDATE plans SET body=json_set(body,'$.pointName','Рыбинск','$.title','Возвращение в Рыбинск','$.text','Ты вернулась в Рыбинск. Можно больше не обниматься через экран. Мы с Чопой и Нафаней очень тебя ждали.') WHERE id='return-home' AND json_extract(body,'$.pointName')='Дом · Рыбинск';
